import sys
from collections import defaultdict

def main():
    import sys
    import threading
    import sys
    sys.setrecursionlimit(1 << 25)
    def input():
        return sys.stdin.read().strip()

    data = input().split()
    index = 0
    T = int(data[index])
    index += 1
    results = []

    def dfs(node, color, graph, visited):
        visited[node] = color
        for neighbor in graph[node]:
            if visited[neighbor] == -1:
                if not dfs(neighbor, 1 - color, graph, visited):
                    return False
            elif visited[neighbor] == color:
                return False
        return True

    for _ in range(T):
        N = int(data[index])
        M = int(data[index + 1])
        index += 2
        graph = defaultdict(list)
        for _ in range(M):
            u = int(data[index]) - 1
            v = int(data[index + 1]) - 1
            index += 2
            graph[u].append(v)
            graph[v].append(u)

        visited = [-1] * N
        valid = True
        for i in range(N):
            if visited[i] == -1:
                if not dfs(i, 0, graph, visited):
                    valid = False
                    break

        if not valid:
            results.append(0)
            continue

        component_sizes = [0] * N
        for i in range(N):
            if visited[i] != -1:
                component_sizes[visited[i]] += 1

        if component_sizes[0] == 0 or component_sizes[1] == 0:
            results.append(0)
        else:
            results.append(2)

    for result in results:
        print(result)

threading.Thread(target=main).start()
